import pandas as pd
raw = pd.Series(["$1,200", "850", "free", "$99.5", "n/a"])
failed = []

def to_price(text):
    try:
        return float(text.replace("$", "").replace(",", ""))
    except ValueError:
        failed.append(text)
        return 0.0

prices = raw.apply(to_price)
print(prices.tolist())
print(len(failed))
